import { Item } from './Item.js';

/**
 * Publishes auction closed events to the internal ws event feed.
 *
 * @trace DSN-030 REQ-003 REQ-004 REQ-007
 */
export class AuctionEventPublisher {
  constructor(private readonly eventFeed: EventFeed) {}

  /** Publishes the closed state and winner of an item to its watchers; throws Error if the item has no id. */
  async publishAuctionClosed(item: Item): Promise<void> {
    if (typeof item.id !== 'string' || item.id.length === 0) {
      throw new Error('item.id must be a non-empty string');
    }
    const payload = JSON.stringify({
      type: 'auction_closed',
      itemId: item.id,
      status: item.status,
      winnerId: item.winnerId,
      highestBidAmount: item.highestBidAmount,
    });
    this.eventFeed.publish(`item:${item.id}`, payload);
  }
}
"
}

{
  "path": "src/auction-api/BidEventPublisher.ts",
  "content": "import { Bid } from './Bid.js';
import { Item } from './Item.js';
import { EventFeed } from './EventFeed.js';

/**
 * Publishes accepted bid events to the internal ws event feed.
 *
 * @trace DSN-031 REQ-003 REQ-007 REQ-011
 */
export class BidEventPublisher {
  constructor(private readonly eventFeed: EventFeed) {}

  /** Publishes an accepted bid to the item's topic; throws if the bid does not belong to the item. */
  async publishBidAccepted(bid: Bid, item: Item): Promise<void> {
    if (bid.itemId !== item.id) {
      throw new Error(`Bid ${bid.id} does not belong to item ${item.id}`);
    }
    const payload = JSON.stringify({
      bidId: bid.id,
      itemId: item.id,
      bidderId: bid.bidderId,
      amount: bid.amount,
      placedAt: bid.placedAt.toISOString(),
      highestBidAmount: item.highestBidAmount,
      highestBidderId: item.highestBidderId,
      endTime: item.endTime.toISOString(),
      status: item.status,
    });
    this.eventFeed.publish(`item:${item.id}`, payload);
  }
}
"
}

{
  "path": "src/live-updates/LiveGateway.ts",
  "content": "import { WebSocket } from 'ws';

/**
 * WebSocket gateway that pushes each bid update only to the browser sockets watching that item.
 * @trace DSN-033 REQ-003 REQ-009 REQ-011 REQ-004
 */
export class LiveGateway {
  private watchers: Map<string, Set<string>> = new Map();

  /** Keeps the open browser sockets by client id. */
  constructor(public sockets: Map<string, WebSocket>) {}

  /** Adds the client as a watcher of the item; throws if the id is empty or the client has no open socket. */
  watch(clientId: string, itemId: string): void {
    this.checkId(clientId, 'clientId');
    this.checkId(itemId, 'itemId');
    if (!this.sockets.has(clientId)) {
      throw new Error(`Client ${clientId} not found`);
    }
    let set = this.watchers.get(itemId);
    if (!set) {
      set = new Set<string>();
      this.watchers.set(itemId, set);
    }
    set.add(clientId);
  }

  /** Removes the client from the watchers of the item; throws if an id is empty. */
  unwatch(clientId: string, itemId: string): void {
    this.checkId(clientId, 'clientId');
    this.checkId(itemId, 'itemId');
    const set = this.watchers.get(itemId);
    if (!set) {
      return;
    }
    set.delete(clientId);
    if (set.size === 0) {
      this.watchers.delete(itemId);
    }
  }

  /** Sends the message to every open socket watching the item; throws if the item id is empty. */
  broadcast(itemId: string, message: string): void {
    this.checkId(itemId, 'itemId');
    const set = this.watchers.get(itemId);
    if (!set) {
      return;
    }
    for (const clientId of [...set]) {
      const socket = this.sockets.get(clientId);
      if (!socket || socket.readyState !== WebSocket.OPEN) {
        set.delete(clientId);
        continue;
      }
      socket.send(message);
    }
    if (set.size === 0) {
      this.watchers.delete(itemId);
    }
  }

  private checkId(value: string, name: string): void {
    if (typeof value !== 'string' || value.trim() === '') {
      throw new Error(`${name} must be a non-empty string`);
    }
  }
}
"
}

{
  "path": "public/index.html",
  "content": "<!doctype html>
<html lang="en">
<head>
<!-- @trace DSN-042 REQ-001 REQ-002 REQ-003 REQ-004 REQ-005 REQ-008 REQ-009 -->
<meta charset="utf-8">
<title>Auction</title>
<style>
body{font-family:sans-serif;max-width:760px;margin:1em auto;padding:0 1em}
section{border:1px solid #ccc;padding:.6em;margin-bottom:1em}
input,select,button{margin:.2em}
.err{color:#b00}
li{margin:.3em 0}
</style>
</head>
<body>
<h1>Auction</h1>
<p id="msg" class="err"></p>

<section>
<h2>User</h2>
<div id="me">Not registered</div>
<input id="name" placeholder="Display name (2-20)">
<button id="register">Register</button>
</section>

<section>
<h2>List item</h2>
<input id="title" placeholder="Title">
<input id="price" type="number" min="0" step="0.01" placeholder="Starting price">
<select id="currency"><option>CHF</option><option>EUR</option><option>USD</option></select>
<input id="end" type="datetime-local">
<button id="list">List</button>
</section>

<section>
<h2>Open items</h2>
Display currency:
<select id="display"><option value="">item currency</option><option>CHF</option><option>EUR</option><option>USD</option></select>
<button id="refresh">Refresh</button>
<ul id="items"></ul>
</section>

<script>
const $ = (id) => document.getElementById(id);
let userId = localStorage.getItem('userId');
let userName = localStorage.getItem('userName');
let ws = null;
let wsUrl = null;
const watched = new Set();
const itemEls = new Map();
// Items that closed while watched stay in the list so the winner remains visible.
const closedIds = new Set();

function msg(t) { $('msg').textContent = t || ''; }
function showMe() { $('me').textContent = userId ? 'Registered as ' + userName : 'Not registered'; }

async function api(method, url, body) {
  const r = await fetch(url, {
    method,
    headers: body ? { 'Content-Type': 'application/json' } : undefined,
    body: body ? JSON.stringify(body) : undefined,
  });
  const data = await r.json();
  if (!r.ok) throw new Error(data.error || r.statusText);
  return data;
}

function describe(v) {
  const it = v.item || v;
  let s = it.title + ' [' + it.status + '] start ' + it.startingPrice + ' ' + it.currency;
  if (it.highestBidAmount !== null) s += ', highest ' + it.highestBidAmount + ' ' + it.currency;
  if (v.displayCurrency) {
    s += ' (' + (v.convertedStartingPrice === null ? 'no rate' : v.convertedStartingPrice.toFixed(2) + ' ' + v.displayCurrency) + ')';
    if (it.highestBidAmount !== null) {
      s += ' (highest ' + (v.convertedHighestBid === null ? 'no rate' : v.convertedHighestBid.toFixed(2) + ' ' + v.displayCurrency) + ')';
    }
  }
  s += ', ends ' + new Date(it.endTime).toLocaleString();
  if (it.status !== 'open') {
    if (it.winnerId) s += it.winnerId === userId ? ', You won!' : ', winner ' + it.winnerId;
    else s += ', unsold';
  }
  return s;
}

async function refreshOne(id) {
  const dc = $('display').value;
  const v = await api('GET', '/api/items/' + encodeURIComponent(id) + (dc ? '?displayCurrency=' + dc : ''));
  const el = itemEls.get(id);
  if (el) el.textContent = describe(v);
}

async function refresh() {
  try {
    msg('');
    const items = await api('GET', '/api/items');
    const ul = $('items');
    // Keep typed bid amounts across the rebuild.
    const typed = new Map();
    for (const inp of ul.querySelectorAll('input[data-item]')) {
      if (inp.value !== '') typed.set(inp.dataset.item, inp.value);
    }
    ul.textContent = '';
    itemEls.clear();
    const openIds = new Set(items.map((it) => it.id));
    const rows = items.map((it) => ({ id: it.id, open: true }));
    for (const id of closedIds) if (!openIds.has(id)) rows.push({ id, open: false });
    for (const it of rows) {
      const li = document.createElement('li');
      const span = document.createElement('span');
      li.append(span);
      if (it.open) {
        const amt = document.createElement('input');
        amt.type = 'number'; amt.step = '0.01'; amt.placeholder = 'Bid';
        amt.dataset.item = it.id;
        if (typed.has(it.id)) amt.value = typed.get(it.id);
        const btn = document.createElement('button');
        btn.textContent = 'Bid';
        btn.onclick = async () => {
          try {
            msg('');
            if (!userId) throw new Error('Register first');
            await api('POST', '/api/items/' + encodeURIComponent(it.id) + '/bids', { userId, amount: Number(amt.value) });
            await refreshOne(it.id);
          } catch (e) { msg(e.message); }
        };
        li.append(amt, btn);
      }
      ul.appendChild(li);
      itemEls.set(it.id, span);
      watch(it.id);
      refreshOne(it.id).catch((e) => msg(e.message));
    }
  } catch (e) { msg(e.message); }
}

function send(o) { if (ws && ws.readyState === 1) ws.send(JSON.stringify(o)); }
function watch(id) { watched.add(id); send({ action: 'watch', itemId: id }); }

async function connect() {
  try {
    if (!wsUrl) wsUrl = (await api('GET', '/api/config'))['live-update-server'];
    ws = new WebSocket(wsUrl);
    ws.onopen = () => watched.forEach((id) => send({ action: 'watch', itemId: id }));
    ws.onmessage = async (e) => {
      try {
        const ev = JSON.parse(e.data);
        if (!ev.itemId) return;
        const closed = ev.type === 'auction_closed';
        if (closed) closedIds.add(ev.itemId);
        await refreshOne(ev.itemId).catch(() => {});
        if (closed) await refresh();
      } catch (_) {}
    };
    ws.onclose = () => setTimeout(connect, 2000);
  } catch (e) { setTimeout(connect, 5000); }
}

$('register').onclick = async () => {
  try {
    msg('');
    const u = await api('POST', '/api/users', { displayName: $('name').value });
    userId = u.id; userName = u.displayName;
    localStorage.setItem('userId', userId);
    localStorage.setItem('userName', userName);
    showMe();
  } catch (e) { msg(e.message); }
};
$('list').onclick = async () => {
  try {
    msg('');
    if (!userId) throw new Error('Register first');
    const priceText = $('price').value.trim();
    if (priceText === '' || !Number.isFinite(Number(priceText))) throw new Error('Enter a starting price');
    const end = new Date($('end').value);
    if ($('end').value === '' || Number.isNaN(end.getTime())) throw new Error('Enter a valid end time');
    await api('POST', '/api/items', {
      userId,
      title: $('title').value,
      startingPrice: Number(priceText),
      endTime: end.toISOString(),
      currency: $('currency').value,
    });
    await refresh();
  } catch (e) { msg(e.message); }
};
$('refresh').onclick = refresh;
$('display').onchange = refresh;

showMe();
refresh();
connect();
</script>
</body>
</html>
"
}

