/**
 * Creates and reads items, and closes auctions whose end time has been reached.
 * @trace DSN-022 REQ-001 REQ-004 REQ-012
 */
export class ItemService {
  constructor(private readonly itemStore: ItemStore, private readonly userStore: UserStore, private readonly auctionEventPublisher: AuctionEventPublisher) {}

  /** Lists a new open item for an existing seller; throws on invalid input, a reserve below the starting price, or unknown seller. */
  async listItem(sellerId: string, title: string, startingPrice: number, endTime: Date, currency: string, reservePrice: number | null): Promise<PublicItem> {
    if (typeof sellerId !== 'string' || sellerId.trim() === '') {
      throw new Error('sellerId must be a non-empty string');
    }
    const seller = await this.userStore.findById(sellerId);
    if (seller === null) {
      throw new Error(`User ${sellerId} not found`);
    }
    if (typeof title !== 'string' || title.trim() === '') {
      throw new Error('title must be a non-empty string');
    }
    if (typeof startingPrice !== 'number' || !Number.isFinite(startingPrice) || startingPrice < 0) {
      throw new Error('startingPrice must be a non-negative number');
    }
    if (!(endTime instanceof Date) || Number.isNaN(endTime.getTime())) {
      throw new Error('endTime must be a valid date');
    }
    if (!(Object.values(Currency) as string[]).includes(currency)) {
      throw new Error('currency must be one of CHF, EUR, USD');
    }
    if (reservePrice !== null && (typeof reservePrice !== 'number' || !Number.isFinite(reservePrice) || reservePrice < startingPrice)) {
      throw new Error('reservePrice must not be below the starting price');
    }
    const item = new Item(
      randomUUID(),
      sellerId,
      title,
      startingPrice,
      reservePrice,
      currency as Currency,
      endTime,
      AuctionStatus.open,
      null,
      null,
      null,
    );
    return toPublic(await this.itemStore.saveItem(item));
  }

  /** Returns the item with the given id; throws if the id is invalid or the item is not found. */
  async getItem(id: string): Promise<PublicItem> {
    if (typeof id !== 'string' || id.trim() === '') {
      throw new Error('id must be a non-empty string');
    }
    const item = await this.itemStore.findItem(id);
    if (item === null) {
      throw new Error(`Item ${id} not found`);
    }
    return toPublic(item);
  }

  /** Returns all items whose auctions are currently open. */
  async listOpenItems(): Promise<PublicItem[]> {
    return (await this.itemStore.findOpenItems()).map(toPublic);
  }

  /** Closes every open auction due at the given time, marking winners or unsold items and publishing each closure. */
  async closeDueAuctions(now: Date): Promise<void> {
    if (!(now instanceof Date) || Number.isNaN(now.getTime())) {
      throw new Error('now must be a valid date');
    }
    const dueItems = await this.itemStore.findDueItems(now);
    for (const item of dueItems) {
      item.close();
      await this.itemStore.saveItem(item);
      await this.auctionEventPublisher.publishAuctionClosed(item);
    }
  }
}

import { DatabaseSync } from 'node:sqlite';
import { Item } from './Item.js';
import { Bid } from './Bid.js';
import { Currency } from './Currency.js';
import { AuctionStatus } from './AuctionStatus.js';

/**
 * Persistence of items and bids, in the API server's SQLite database.
 *
 * @trace DSN-029 REQ-001 REQ-002 REQ-004 REQ-012
 */
export class ItemStore {
  private readonly db: DatabaseSync;

  constructor(db: DatabaseSync) {
    this.db = db;
    this.db.exec(`CREATE TABLE IF NOT EXISTS items (
      id TEXT PRIMARY KEY,
      sellerId TEXT NOT NULL,
      title TEXT NOT NULL,
      startingPrice REAL NOT NULL,
      reservePrice REAL,
      currency TEXT NOT NULL,
      endTime TEXT NOT NULL,
      status TEXT NOT NULL,
      highestBidAmount REAL,
      highestBidderId TEXT,
      winnerId TEXT
    )`);
    // Databases created before the reserve price existed lack the column.
    const columns = this.db.prepare('PRAGMA table_info(items)').all() as unknown as { name: string }[];
    if (!columns.some((c) => c.name === 'reservePrice')) {
      this.db.exec('ALTER TABLE items ADD COLUMN reservePrice REAL');
    }
    this.db.exec(`CREATE TABLE IF NOT EXISTS bids (
      id TEXT PRIMARY KEY,
      itemId TEXT NOT NULL,
      bidderId TEXT NOT NULL,
      amount REAL NOT NULL,
      placedAt TEXT NOT NULL
    )`);
  }

  /** Inserts the item if its id is new, otherwise updates its stored row. */
  async saveItem(item: Item): Promise<Item> {
    const exists = this.db.prepare('SELECT id FROM items WHERE id = ?').get(item.id) !== undefined;
    if (exists) {
      this.db
        .prepare(`UPDATE items SET sellerId = ?, title = ?, startingPrice = ?, reservePrice = ?, currency = ?, endTime = ?,
          status = ?, highestBidAmount = ?, highestBidderId = ?, winnerId = ? WHERE id = ?`)
        .run(
          item.sellerId,
          item.title,
          item.startingPrice,
          item.reservePrice,
          item.currency,
          item.endTime.toISOString(),
          item.status,
          item.highestBidAmount,
          item.highestBidderId,
          item.winnerId,
          item.id,
        );
    } else {
      this.db
        .prepare(`INSERT INTO items (id, sellerId, title, startingPrice, reservePrice, currency, endTime, status,
          highestBidAmount, highestBidderId, winnerId) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`)
        .run(
          item.id,
          item.sellerId,
          item.title,
          item.startingPrice,
          item.reservePrice,
          item.currency,
          item.endTime.toISOString(),
          item.status,
          item.highestBidAmount,
          item.highestBidderId,
          item.winnerId,
        );
    }
    return item;
  }

  /** Returns the item with the given id, or null when it is not stored. */
  async findItem(id: string): Promise<Item | null> {
    const row = this.db.prepare('SELECT * FROM items WHERE id = ?').get(id);
    if (row === undefined) {
      return null;
    }
    return this.toItem(row as unknown as ItemRow);
  }

  /** Returns all items whose status is open, the one ending soonest first. */
  async findOpenItems(): Promise<Item[]> {
    const rows = this.db
      .prepare('SELECT * FROM items WHERE status = ? ORDER BY endTime ASC')
      .all(AuctionStatus.open) as unknown as ItemRow[];
    return rows.map((row) => this.toItem(row));
  }

  /** Returns the open items whose end time is not after the given instant. */
  async findDueItems(now: Date): Promise<Item[]> {
    const rows = this.db
      .prepare('SELECT * FROM items WHERE status = ? AND endTime <= ? ORDER BY endTime ASC')
      .all(AuctionStatus.open, now.toISOString()) as unknown as ItemRow[];
    return rows.map((row) => this.toItem(row));
  }

  /** Inserts the bid if its id is new, otherwise updates its stored row. */
  async saveBid(bid: Bid): Promise<Bid> {
    const exists = this.db.prepare('SELECT id FROM bids WHERE id = ?').get(bid.id) !== undefined;
    if (exists) {
      this.db
        .prepare('UPDATE bids SET itemId = ?, bidderId = ?, amount = ?, placedAt = ? WHERE id = ?')
        .run(bid.itemId, bid.bidderId, bid.amount, bid.placedAt.toISOString(), bid.id);
    } else {
      this.db
        .prepare('INSERT INTO bids (id, itemId, bidderId, amount, placedAt) VALUES (?, ?, ?, ?, ?)')
        .run(bid.id, bid.itemId, bid.bidderId, bid.amount, bid.placedAt.toISOString());
    }
    return bid;
  }

  private toItem(row: ItemRow): Item {
    return new Item(
      row.id,
      row.sellerId,
      row.title,
      row.startingPrice,
      row.reservePrice,
      row.currency as Currency,
      new Date(row.endTime),
      row.status as AuctionStatus,
      row.highestBidAmount,
      row.highestBidderId,
      row.winnerId,
    );
  }
}

type ItemRow = {
  id: string;
  sellerId: string;
  title: string;
  startingPrice: number;
  reservePrice: number | null;
  currency: string;
  endTime: string;
  status: string;
  highestBidAmount: number | null;
  highestBidderId: string | null;
  winnerId: string | null;
};

