import { Item } from './Item.js';
import { ItemStore } from './ItemStore.js';
import { UserStore } from './UserStore.js';
import { BidEventPublisher } from './BidEventPublisher.js';

/**
 * Validates and stores bids, extends end time, and publishes accepted bids to the event feed.
 *
 * @trace DSN-023 REQ-002 REQ-009 REQ-003 REQ-011 REQ-012
 */
export class BidService {
  constructor(
    private readonly itemStore: ItemStore,
    private readonly bidEventPublisher: BidEventPublisher,
    private readonly userStore: UserStore,
  ) {}

  /** Validates a bid, extends the end time when late, stores it and publishes it; throws on invalid input, unknown item or user, or a rejected bid. */
  async placeBid(itemId: string, bidderId: string, amount: number): Promise<Bid> {
    if (typeof itemId !== 'string' || itemId.length === 0) {
      throw new Error('itemId must be a non-empty string');
    }
    if (typeof bidderId !== 'string' || bidderId.length === 0) {
      throw new Error('bidderId must be a non-empty string');
    }
    if (typeof amount !== 'number' || !Number.isFinite(amount) || amount <= 0) {
      throw new Error('amount must be a positive number');
    }

    const item: Item | null = await this.itemStore.findItem(itemId);
    if (item === null) {
      throw new Error(`Item ${itemId} not found`);
    }
    const bidder = await this.userStore.findById(bidderId);
    if (bidder === null) {
      throw new Error(`User ${bidderId} not found`);
    }

    const now = new Date();
    if (item.sellerId === bidderId) {
      throw new Error('Seller cannot bid on their own item');
    }
    if (!item.isOpen(now)) {
      throw new Error(`Item ${itemId} is not open for bids`);
    }
    if (amount < item.minimumBid()) {
      throw new Error(`Bid ${amount} is below the minimum bid ${item.minimumBid()}`);
    }

    item.extendIfLate(now);
    item.recordBid(bidderId, amount);
    const bid = new Bid(randomUUID(), itemId, bidderId, amount, now);

    const savedBid = await this.itemStore.saveBid(bid);
    await this.itemStore.saveItem(item);
    await this.bidEventPublisher.publishBidAccepted(savedBid, item);
    return savedBid;
  }
}

import { WebSocket } from 'ws';

/**
 * WebSocket gateway that pushes each bid update only to the browser sockets watching that item.
 * @trace DSN-033 REQ-003 REQ-009 REQ-011 REQ-004 REQ-012
 */
export class LiveGateway {
  private watchers: Map<string, Set<string>> = new Map();

  /** Keeps the open browser sockets by client id. */
  constructor(public sockets: Map<string, WebSocket>) {}

  /** Adds the client as a watcher of the item; throws if the id is empty or the client has no open socket. */
  watch(clientId: string, itemId: string): void {
    this.checkId(clientId, 'clientId');
    this.checkId(itemId, 'itemId');
    if (!this.sockets.has(clientId)) {
      throw new Error(`Client ${clientId} not found`);
    }
    let set = this.watchers.get(itemId);
    if (!set) {
      set = new Set<string>();
      this.watchers.set(itemId, set);
    }
    set.add(clientId);
  }

  /** Removes the client from the watchers of the item; throws if an id is empty. */
  unwatch(clientId: string, itemId: string): void {
    this.checkId(clientId, 'clientId');
    this.checkId(itemId, 'itemId');
    const set = this.watchers.get(itemId);
    if (!set) {
      return;
    }
    set.delete(clientId);
    if (set.size === 0) {
      this.watchers.delete(itemId);
    }
  }

  /** Sends the message to every open socket watching the item; throws if the item id is empty. */
  broadcast(itemId: string, message: string): void {
    this.checkId(itemId, 'itemId');
    const set = this.watchers.get(itemId);
    if (!set) {
      return;
    }
    for (const clientId of [...set]) {
      const socket = this.sockets.get(clientId);
      if (!socket || socket.readyState !== WebSocket.OPEN) {
        set.delete(clientId);
        continue;
      }
      socket.send(message);
    }
    if (set.size === 0) {
      this.watchers.delete(itemId);
    }
  }

  private checkId(value: string, name: string): void {
    if (typeof value !== 'string' || value.trim() === '') {
      throw new Error(`${name} must be a non-empty string`);
    }
  }
}

import express, { type Express, type NextFunction, type Request, type Response } from 'express';
import { DatabaseSync } from 'node:sqlite';
import { fileURLToPath } from 'node:url';
import type { WebSocket } from 'ws';
import { UserStore } from '../auction-api/UserStore.js';
import { ItemStore } from '../auction-api/ItemStore.js';
import { EventFeed } from '../auction-api/EventFeed.js';
import { AuctionEventPublisher } from '../auction-api/AuctionEventPublisher.js';
import { BidEventPublisher } from '../auction-api/BidEventPublisher.js';
import { UserService } from '../auction-api/UserService.js';
import { ItemService } from '../auction-api/ItemService.js';
import { BidService } from '../auction-api/BidService.js';
import { AuctionCloser } from '../auction-api/AuctionCloser.js';
import { UserController } from '../auction-api/UserController.js';
import { ItemController } from '../auction-api/ItemController.js';
import { BidController } from '../auction-api/BidController.js';
import { FrankfurterClient } from '../exchange-rates/FrankfurterClient.js';
import { ExchangeRateService } from '../exchange-rates/ExchangeRateService.js';

export function createApp(db: DatabaseSync = new DatabaseSync(':memory:')): Express {
  const userStore = new UserStore(db);
  const itemStore = new ItemStore(db);
  const eventFeed = new EventFeed(new Set<WebSocket>());
  const auctionEventPublisher = new AuctionEventPublisher(eventFeed);
  const bidEventPublisher = new BidEventPublisher(eventFeed);
  const frankfurterClient = new FrankfurterClient();
  // Rates are cached for 1 hour, as the design states.
  const exchangeRateService = new ExchangeRateService(frankfurterClient, 60 * 60 * 1000);
  const userService = new UserService(userStore);
  const itemService = new ItemService(itemStore, userStore, auctionEventPublisher);
  const bidService = new BidService(itemStore, bidEventPublisher, userStore);
  // Default check interval: 5 seconds.
  const auctionCloser = new AuctionCloser(itemService, 5000);
  const userController = new UserController(userService);
  const itemController = new ItemController(itemService, exchangeRateService);
  const bidController = new BidController(bidService);

  const app = express();
  app.locals.eventFeed = eventFeed;
  app.locals.auctionCloser = auctionCloser;

  app.get('/health', (_req, res) => {
    res.json({ status: 'ok' });
  });
  app.use(express.json());
  app.use(express.static(fileURLToPath(new URL('../../public', import.meta.url))));

  app.get('/api/config', (_req, res) => {
    res.json({ 'live-update-server': process.env.LIVE_UPDATE_SERVER_PUBLIC_URL ?? 'ws://localhost:8081' });
  });

  app.post('/api/users', async (req, res) => {
    res.status(201).json(await userController.register(req.body?.displayName));
  });
  app.post('/api/items', async (req, res) => {
    const b = req.body ?? {};
    res.status(201).json(await itemController.listItem(b.userId, b.title, b.startingPrice, b.endTime, b.currency, b.reservePrice ?? null));
  });
  app.get('/api/items', async (_req, res) => {
    res.json(await itemController.listOpenItems());
  });
  app.get('/api/items/:id', async (req, res) => {
    const dc = req.query.displayCurrency;
    res.json(await itemController.getItem(String(req.params.id), typeof dc === 'string' && dc !== '' ? dc : undefined));
  });
  app.post('/api/items/:id/bids', async (req, res) => {
    const b = req.body ?? {};
    res.status(201).json(await bidController.placeBid(String(req.params.id), b.userId, b.amount));
  });

  app.use((err: unknown, _req: Request, res: Response, _next: NextFunction) => {
    const message = err instanceof Error ? err.message : String(err);
    res.status(message.endsWith('not found') ? 404 : 400).json({ error: message });
  });

  return app;
}

